import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { useEffect, useMemo, useState } from 'react';
import { operationsApi } from '../../api/operationsApi.js';
import { planningApi } from '../../api/client.js';

const stages = [
  ['network', 'Network Overview'], ['maintenance-data', 'Maintenance Data'], ['risk-clock', 'RiskClock'], ['priority', 'Priority Score'], ['block-planning', 'Block Planning'], ['coa', 'COA Integration'], ['timetable', 'Train Timetable'], ['goods-forecast', 'Goods Forecast'], ['bundler', 'Block Bundler'], ['conflict-shield', 'Conflict Shield / Ripple Check'], ['optimization', 'CP-SAT Optimization'], ['candidate-plans', 'Candidate Plans'], ['monte-carlo', 'Monte Carlo Simulation'], ['risk-analysis', 'Risk Analysis'], ['gati-score', 'GATI Score'], ['explainability', 'Show Your Work'], ['trade-off', 'Trade-Off Dial'], ['final-plan', 'Final Recommended Plan'], ['weekly-plan', 'Weekly Plan'], ['monthly-plan', 'Monthly Plan'], ['approval', 'CTO Approval'], ['publish', 'Publish']
];
const stageStatus = (id, data) => {
  if (id === 'maintenance-data') return data?.stages?.maintenance || 'PENDING';
  if (id === 'priority') return data?.stages?.priority || 'PENDING';
  if (['candidate-plans', 'final-plan'].includes(id)) return data?.stages?.planning || 'PENDING';
  if (id === 'approval') return data?.stages?.approval || 'PENDING';
  if (id === 'publish') return data?.stages?.publish || 'PENDING';
  return 'PENDING';
};

function useWorkflow() {
  const [state, setState] = useState({ loading: true, error: '', data: null });
  const refresh = async () => {
    try { const response = await operationsApi.workflowOverview(); setState({ loading: false, error: '', data: response.data.data }); }
    catch (error) { setState({ loading: false, error: error.response?.data?.detail || 'The workflow data could not be loaded.', data: null }); }
  };
  useEffect(() => { refresh(); }, []);
  return { ...state, refresh };
}
function Breadcrumb({ title }) { return <nav className="breadcrumb" aria-label="Breadcrumb"><Link to="/">Control center</Link><span>/</span><Link to="/workflow">Workflow</Link><span>/</span><strong>{title}</strong></nav>; }
function LoadingSkeleton() { return <div className="skeleton-stack" aria-label="Loading"><i /><i /><i /></div>; }
function StateMessage({ error, children }) { return <div className={error ? 'workflow-message error-state' : 'workflow-message'}><strong>{error ? 'Unable to load this stage' : 'No operational data yet'}</strong><p>{error || children}</p></div>; }
function Toast({ message, error = false }) { return message ? <div className={`workflow-toast ${error ? 'error' : ''}`} role="status">{message}</div> : null; }
function PageFrame({ title, eyebrow, children }) { return <main className="content"><Breadcrumb title={title} /><header><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1></div></header>{children}</main>; }

export function Workflow() {
  const { loading, error, data } = useWorkflow();
  return <PageFrame title="Planning workflow" eyebrow="RAILVISTA DECISION PIPELINE"><section className="operations-content">{loading ? <LoadingSkeleton /> : error ? <StateMessage error={error} /> : <><div className="workflow-summary"><span className="signal-dot" />Live corridor: {data.corridorId}</div><div className="workflow-nodes">{stages.map(([id, name], index) => <motion.div key={id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * .025 }} className="workflow-node-wrap"><Link className="workflow-node" to={`/workflow/${id}`}><span className="node-index">{String(index + 1).padStart(2, '0')}</span><strong>{name}</strong><span className={`stage-status ${stageStatus(id, data).toLowerCase()}`}>{stageStatus(id, data)}</span></Link>{index < stages.length - 1 && <span className="workflow-connector" />}</motion.div>)}</div></>}</section></PageFrame>;
}

export function LegacyNetworkOverview() {
  const { loading, error, data } = useWorkflow();
  return <PageFrame title="Network overview" eyebrow="CORRIDOR ASSET REGISTER"><section className="operations-content">{loading ? <LoadingSkeleton /> : error ? <StateMessage error={error} /> : <><div className="metric-grid"><Metric label="Track sections" value={data.trackSections} note="Registered sections" /><Metric label="Stations" value={data.stations} note="Registered stations" /><Metric label="Assets" value={data.assets} note="From maintenance register" /><Metric label="Critical alerts" value={data.criticalAlerts} note="Open severity 4–5 tasks" /></div><article className="panel"><div className="panel-heading"><div><p className="eyebrow">DEPARTMENT OWNERSHIP</p><h3>Current corridor workload</h3></div><span className="status">{data.corridorId}</span></div>{data.departments.map((department) => <div className="plan-row" key={department.department}><strong>{department.department}</strong><span>{department.tasks} maintenance items</span></div>)}{!data.tasks.length && <StateMessage>Import maintenance demand to populate the corridor asset view.</StateMessage>}</article></>}</section></PageFrame>;
}

export function NetworkOverview() {
  const { loading, error, data } = useWorkflow();
  const [selected, setSelected] = useState(null);
  if (loading || error) return <PageFrame title="Network overview" eyebrow="CORRIDOR ASSET REGISTER"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  const tasks = data.tasks || []; const departments = data.departments || [];
  const critical = tasks.filter((task) => task.severity >= 4 && task.status !== 'COMPLETED').length;
  const warning = tasks.filter((task) => task.severity === 3 && task.status !== 'COMPLETED').length;
  const healthy = Math.max(0, data.assets - critical - warning); const health = data.assets ? Math.max(55, Math.round(100 - ((critical * 9 + warning * 4) / data.assets))) : 92;
  const stationRows = data.stationsData || []; const stationCount = Math.max(2, stationRows.length);
  const stations = stationRows.map((station, index) => ({ id: station.stationId, name: station.name, type: 'STATION', x: 65 + index * (610 / Math.max(1, stationCount - 1)), y: 150 }));
  const assets = tasks.slice(0, 8).map((task, index) => ({ ...task, id: task._id, name: task.assetId, type: 'ASSET', x: 120 + (index % 5) * 125, y: index % 2 ? 88 : 215 }));
  const active = selected || assets[0] || stations[0]; const risk = (active?.severity ?? 1) >= 4 ? 'Critical' : active?.severity === 3 ? 'Warning' : 'Controlled';
  const readiness = [['Network Loaded', data.trackSections > 0], ['Maintenance Imported', tasks.length > 0], ['Assets Registered', data.assets > 0], ['Departments Linked', departments.some((department) => department.tasks > 0)]]; const ready = readiness.every(([, value]) => value);
  const workloadMax = Math.max(...departments.map((department) => department.tasks), 1);
  return <PageFrame title="Network overview" eyebrow="CORRIDOR ASSET REGISTER"><section className="operations-content">
    <style>{`.network-card{transition:transform .2s,box-shadow .2s}.network-card:hover{transform:translateY(-3px);box-shadow:0 16px 30px rgba(36,83,123,.13)}.network-health{display:grid;gap:12px;margin-top:16px}.network-health b{color:#194f7b;font-size:30px}.network-meter,.workload-meter{height:9px;overflow:hidden;border-radius:999px;background:#e2edf5}.network-meter i,.workload-meter b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#38ba85,#79cdaa)}.network-layout{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:16px;margin-top:16px}.network-canvas{min-height:330px;overflow:hidden;border:1px solid #d5e5f1;border-radius:12px;background:radial-gradient(circle at 20% 12%,#fbfeff,#e7f3fb)}.network-canvas svg{width:100%;min-width:610px;height:330px}.net-rail{fill:none;stroke:#4f7188;stroke-width:4}.net-sleeper{fill:none;stroke:#d7e5ee;stroke-width:23;stroke-dasharray:2 12}.net-block{fill:none;stroke:#e05252;stroke-width:18px;stroke-linecap:round;opacity:.72}.net-station,.net-asset{cursor:pointer}.net-station circle{fill:#fff;stroke:#197fc1;stroke-width:4;transition:r .2s}.net-station:hover circle{r:11}.net-station text,.net-asset text{fill:#315a78;font-size:11px;font-weight:800;paint-order:stroke;stroke:#f8fcff;stroke-width:4px;stroke-linejoin:round}.net-asset circle{stroke:#fff;stroke-width:3;transition:r .2s}.net-asset:hover circle{r:12}.net-asset.critical circle{fill:#db4d5b}.net-asset.warning circle{fill:#e7ad48}.net-asset.healthy circle{fill:#42b98a}.asset-detail{padding:18px;border:1px solid #d6e6f1;border-radius:12px;background:#fbfdff}.asset-detail h4{margin:4px 0 15px;color:#204d76;font-size:19px}.asset-detail dl{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0 0}.asset-detail dt{color:#7890a5;font-size:9px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.asset-detail dd{margin:4px 0 0;color:#345470;font-size:12px;font-weight:700}.asset-pill{display:inline-flex;padding:5px 8px;border-radius:999px;background:#e5f3ea;color:#187454;font-size:10px;font-weight:800}.asset-pill.critical{background:#ffe6e9;color:#aa3746}.asset-pill.warning{background:#fff0d4;color:#956219}.asset-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}.asset-summary article{padding:14px;border:1px solid #dce8f1;border-radius:11px;background:#fbfdff}.asset-summary .healthy{border-top:3px solid #38ba85}.asset-summary .warning{border-top:3px solid #e7ad48}.asset-summary .critical{border-top:3px solid #dc5562}.asset-summary strong{display:block;margin-top:6px;color:#285476;font-size:24px}.asset-summary small{color:#71879a;font-size:10px;font-weight:800}.readiness{display:grid;gap:9px;margin-top:16px}.ready-row{display:flex;align-items:center;gap:8px;padding:9px;border-radius:8px;background:#f8fcff;color:#668095;font-size:11px;font-weight:700}.ready-row i{display:grid;width:18px;height:18px;place-items:center;border-radius:50%;background:#dff4e9;color:#167b56;font-style:normal}.ready-row.wait i{background:#fff0d2;color:#9b6818}.ready-row b{margin-left:auto;color:#31546e}.workload-row{display:grid;grid-template-columns:90px minmax(0,1fr) 28px;align-items:center;gap:10px;padding:12px 0;border-top:1px solid #dce8f1;color:#365672;font-size:12px;font-weight:800}@media(max-width:800px){.network-layout{grid-template-columns:1fr}.network-canvas{overflow-x:auto}}@media(max-width:520px){.asset-summary{grid-template-columns:1fr}.workload-row{grid-template-columns:78px minmax(0,1fr) 25px}}`}</style>
    <div className="metric-grid"><motion.div className="network-card" whileHover={{ y: -3 }}><Metric label="Track sections" value={data.trackSections} note="Registered sections" /></motion.div><motion.div className="network-card" whileHover={{ y: -3 }}><Metric label="Stations" value={data.stations} note="Corridor nodes" /></motion.div><motion.div className="network-card" whileHover={{ y: -3 }}><Metric label="Assets" value={data.assets} note="From maintenance register" /></motion.div><motion.div className="network-card" whileHover={{ y: -3 }}><Metric label="Critical alerts" value={data.criticalAlerts} note="Open severity 4–5 tasks" /></motion.div></div>
    <section className="workspace"><article className="panel"><p className="eyebrow">NETWORK HEALTH</p><h3>Ready-state across the corridor</h3><div className="network-health"><span>Overall health</span><b>{health}%</b><div className="network-meter"><i style={{ width: `${health}%` }} /></div><div className="plan-row"><strong>Operational status</strong><span className="status">{critical ? 'WATCH' : 'STABLE'}</span></div><div className="plan-row"><strong>Critical sections</strong><span>{critical}</span></div><div className="plan-row"><strong>Available assets</strong><span>{healthy}</span></div></div></article><article className="panel"><p className="eyebrow">AI PLANNING READINESS</p><h3>{ready ? 'Ready for AI planning' : 'Waiting for network inputs'}</h3><div className="readiness">{readiness.map(([label, value]) => <div className={`ready-row ${value ? '' : 'wait'}`} key={label}><i>{value ? '✓' : '…'}</i>{label}<b>{value ? 'Ready' : 'Waiting'}</b></div>)}<div className={`ready-row ${ready ? '' : 'wait'}`}><i>{ready ? '✓' : '…'}</i>Ready for AI Planning<b>{ready ? 'Ready' : 'Waiting'}</b></div></div></article></section>
    <article className="panel"><div className="panel-heading"><div><p className="eyebrow">INTERACTIVE CORRIDOR</p><h3>Assets, maintenance locations, and possession sections</h3></div><span className="status">{data.corridorId}</span></div><div className="network-layout"><div className="network-canvas"><svg viewBox="0 0 740 300" role="application" aria-label="Interactive railway corridor"><path className="net-sleeper" d="M42 150 L696 150" /><path className="net-rail" d="M42 142 L696 142" /><path className="net-rail" d="M42 158 L696 158" />{data.activeBlocks > 0 && <path className="net-block" d="M285 150 L430 150" />}{stations.map((station) => <g className="net-station" key={station.id} onClick={() => setSelected(station)}><circle cx={station.x} cy={station.y} r="8" /><text x={station.x} y={station.y - 17} textAnchor="middle">{station.name}</text></g>)}{assets.map((asset) => <g className={`net-asset ${asset.severity >= 4 ? 'critical' : asset.severity === 3 ? 'warning' : 'healthy'}`} key={asset.id} onClick={() => setSelected(asset)}><circle cx={asset.x} cy={asset.y} r="8" /><text x={asset.x + 12} y={asset.y + 4}>{asset.name}</text><text x={asset.x + 12} y={asset.y + 18}>{asset.department}</text></g>)}</svg></div><aside className="asset-detail"><p className="eyebrow">SELECTED {active?.type || 'ASSET'}</p><h4>{active?.name || 'Corridor asset'}</h4><span className={`asset-pill ${risk.toLowerCase()}`}>{risk} risk</span><dl><div><dt>Department</dt><dd>{active?.department || 'Rail operations'}</dd></div><div><dt>Status</dt><dd>{active?.status || (active?.type === 'STATION' ? 'Operational' : 'Open maintenance')}</dd></div><div><dt>Severity</dt><dd>{active?.severity ?? 1} / 5</dd></div><div><dt>Last maintenance</dt><dd>14 days ago</dd></div><div><dt>Upcoming maintenance</dt><dd>{active?.dueAt ? new Date(active.dueAt).toLocaleDateString('en-IN') : 'Scheduled review'}</dd></div><div><dt>Possession status</dt><dd>{data.activeBlocks ? 'Active block watch' : 'No active possession'}</dd></div></dl></aside></div>{!tasks.length && <StateMessage>Maintenance data is unavailable. The corridor map is showing the operational network fallback.</StateMessage>}</article>
    <section className="workspace"><article className="panel"><p className="eyebrow">ASSET STATUS SUMMARY</p><h3>Condition by maintenance severity</h3><div className="asset-summary"><article className="healthy"><small>HEALTHY ASSETS</small><strong>{healthy}</strong><span className="status">Operational</span></article><article className="warning"><small>WARNING ASSETS</small><strong>{warning}</strong><span className="stage-status cto_review">Monitor</span></article><article className="critical"><small>CRITICAL ASSETS</small><strong>{critical}</strong><span className="stage-status failed">Action required</span></article></div></article><article className="panel"><div className="panel-heading"><div><p className="eyebrow">DEPARTMENT OWNERSHIP</p><h3>Current corridor workload</h3></div><span className="status">{data.corridorId}</span></div>{departments.map((department) => <div className="workload-row" key={department.department}><span>{department.department}</span><i className="workload-meter"><b style={{ width: `${Math.round(department.tasks / workloadMax * 100)}%` }} /></i><strong>{department.tasks}</strong></div>)}</article></section>
  </section></PageFrame>;
}

function OptimizationStage() {
  const { loading, error, data, refresh } = useWorkflow();
  const [selectedId, setSelectedId] = useState('');
  const [execution, setExecution] = useState({ phase: 'READY', error: '' });
  const plans = data?.plans || []; const run = data?.optimizationRun; const evidence = run?.evidence;
  const selected = useMemo(() => plans.find((plan) => String(plan._id) === selectedId) || plans[0], [plans, selectedId]);
  async function runOptimization() {
    if (execution.running) return;
    setExecution({ running: true, error: '' });
    try {
      await planningApi.generate({ corridorId: data.corridorId });
      await refresh();
      setExecution({ running: false, error: '' });
    } catch (requestError) {
      setExecution({ running: false, error: requestError.response?.data?.detail || 'Optimization could not be started.' });
    }
  }
  if (loading || error) return <PageFrame title="CP-SAT Optimization" eyebrow="OR-TOOLS SOLVER EVIDENCE"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  if (!run) return <PageFrame title="CP-SAT Optimization" eyebrow="OR-TOOLS SOLVER EVIDENCE"><section className="operations-content"><article className="panel"><span className="stage-status pending">{execution.running ? 'CP-SAT OPTIMIZATION RUNNING' : 'NO OPTIMIZATION RUN YET'}</span><h3>{execution.running ? 'Running the authoritative planning workflow…' : 'CP-SAT has not been executed for the current planning data.'}</h3><p className="muted">Initial runs use the backend default profile sequence and persisted corridor inputs. The same workflow then performs simulation, risk calculation, and GATI scoring before candidates are saved.</p>{execution.error && <div className="workflow-message error-state"><strong>OPTIMIZATION FAILED</strong><p>{execution.error}</p></div>}<button className="primary" onClick={runOptimization} disabled={execution.running}>{execution.running ? 'Running optimization…' : 'Run CP-SAT Optimization'}</button></article></section></PageFrame>;
  const inputs = evidence?.inputs || {}; const profiles = evidence?.profiles || [];
  return <PageFrame title="CP-SAT Optimization" eyebrow="OR-TOOLS SOLVER EVIDENCE"><section className="operations-content">
    <style>{`.solver-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.solver-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.solver-list{display:grid;gap:9px;margin-top:14px}.solver-list div{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-top:1px solid #dce8f1;color:#59738e;font-size:12px}.solver-list b{color:#264f70;text-align:right}.solver-table tr{cursor:pointer}.solver-table tr.selected{background:#eef7fc}.solver-evidence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.solver-evidence span{padding:11px;border-radius:9px;background:#f7fbfe;color:#668095;font-size:11px}.solver-evidence b{display:block;margin-top:4px;color:#254e70;font-size:13px}@media(max-width:800px){.solver-grid,.solver-columns,.solver-evidence{grid-template-columns:1fr 1fr}}@media(max-width:520px){.solver-grid,.solver-columns,.solver-evidence{grid-template-columns:1fr}}`}</style>
    <div className="workflow-summary"><span className="signal-dot" />Planning run {run.id} · {run.status}</div>
    {run.status === 'FAILED' && <div className="workflow-message error-state"><strong>OPTIMIZATION FAILED</strong><p>{run.errorDetail || 'The planning workflow did not produce a candidate.'}</p><button className="primary" onClick={runOptimization} disabled={execution.running}>{execution.running ? 'Running optimization…' : 'Retry Optimization'}</button></div>}
    {run.status === 'INFEASIBLE' && <div className="workflow-message error-state"><strong>CP-SAT STATUS: INFEASIBLE</strong><p>{run.errorDetail || 'The persisted solver evidence below describes why no candidate could be created.'}</p><button className="primary" onClick={runOptimization} disabled={execution.running}>{execution.running ? 'Running optimization…' : 'Retry Optimization'}</button></div>}
    {run.status === 'RUNNING' && <div className="workflow-message"><strong>CP-SAT OPTIMIZATION RUNNING</strong><p>The planning run is active; persisted solver evidence will appear when it completes.</p></div>}
    {!evidence ? <article className="panel"><span className={`stage-status ${run.status === 'INFEASIBLE' ? 'failed' : 'failed'}`}>{run.status === 'INFEASIBLE' ? 'CP-SAT STATUS: INFEASIBLE' : 'OPTIMIZATION FAILED'}</span><h3>{run.status === 'INFEASIBLE' ? 'The model has no feasible solution.' : 'No solver evidence was persisted for this run.'}</h3><p className="muted">{run.errorDetail || 'This is a legacy run. Start a new planning run to store CP-SAT diagnostics.'}</p><button className="primary" onClick={runOptimization} disabled={execution.running}>{execution.running ? 'Running optimization…' : 'Retry Optimization'}</button>{execution.error && <div className="workflow-message error-state"><p>{execution.error}</p></div>}</article> : <>
      <div className="solver-grid"><Metric label="Tasks received" value={inputs.tasks} note="Priority-scored maintenance" /><Metric label="Solver units" value={inputs.units} note="Tasks plus compatible bundles" /><Metric label="Feasible choices" value={inputs.feasible_options} note="Boolean variables created" /><Metric label="Candidate plans" value={plans.length} note="Persisted CP-SAT output" /></div>
      <section className="solver-columns"><article className="panel"><p className="eyebrow">SOLVER DECISION</p><h3>Task/bundle × COA possession</h3><p className="muted">{evidence.decision}</p><div className="solver-list"><div><span>Engine</span><b>{evidence.engine}</b></div><div><span>Profiles solved</span><b>{profiles.length}</b></div><div><span>Candidate mechanism</span><b>Three weight profiles + diversity constraint</b></div></div></article><article className="panel"><p className="eyebrow">OPTIMIZATION OBJECTIVE</p><h3>Maximize implemented trade-offs</h3><p className="muted">{evidence.objective}</p><div className="solver-list"><div><span>Priority</span><b>Positive weight</b></div><div><span>Availability impact / duration</span><b>Positive weight</b></div><div><span>Bundle time saved</span><b>+50 per minute</b></div><div><span>Overlapping freight demand</span><b>Negative weight</b></div></div></article></section>
      <section className="solver-columns"><article className="panel"><p className="eyebrow">HARD CONSTRAINTS</p><h3>Model constraints and pre-filters</h3><div className="solver-list">{[...(evidence.hard_constraints || []), ...(evidence.pre_filters || [])].map((item) => <div key={item}><span>{item}</span><b>HARD</b></div>)}</div></article><article className="panel"><p className="eyebrow">INPUT FEASIBILITY</p><h3>What reached CP-SAT</h3><div className="solver-list"><div><span>COA windows / usable</span><b>{inputs.coa_windows} / {inputs.usable_coa_windows}</b></div><div><span>Rejected before solver</span><b>{inputs.rejected_before_solver}</b></div>{Object.entries(inputs.exclusions || {}).filter(([, count]) => count).map(([reason, count]) => <div key={reason}><span>{reason}</span><b>{count}</b></div>)}</div></article></section>
      <article className="panel"><p className="eyebrow">SOLVER INPUT LINEAGE</p><h3>What is connected to this model</h3><div className="solver-evidence"><span>Maintenance demand<b>DIRECT SOLVER INPUT</b></span><span>RiskClock / Priority<b>DIRECT OBJECTIVE INPUT</b></span><span>COA / timetable<b>PRE-FILTERED BEFORE SOLVER</b></span><span>Goods forecast<b>OBJECTIVE PENALTY</b></span><span>Block Bundler<b>DIRECT SOLVER UNITS</b></span><span>Conflict Shield<b>NOT CURRENTLY CONNECTED</b></span></div><p className="muted">Conflict Shield is separate review evidence. The optimizer independently applies its own train, capacity, and resource logic.</p></article>
      <article className="panel"><div className="panel-heading"><div><p className="eyebrow">CANDIDATE OUTPUT</p><h3>Real OR-Tools solves</h3></div><span className="status">Select a candidate</span></div>{plans.length ? <div className="table-wrap solver-table"><table><thead><tr><th>Candidate</th><th>Status</th><th>Scheduled work</th><th>Possessions</th><th>Objective</th><th>Profile</th></tr></thead><tbody>{plans.map((plan) => <tr key={plan._id} onClick={() => setSelectedId(String(plan._id))} className={selected?._id === plan._id ? 'selected' : ''}><td><strong>{plan.name}</strong></td><td>{plan.solver?.status}</td><td>{new Set((plan.blocks || []).flatMap((block) => block.taskIds || [])).size}</td><td>{plan.blocks?.length || 0}</td><td>{plan.solver?.objective ?? '—'}</td><td>{plan.solver?.profile ?? '—'}</td></tr>)}</tbody></table></div> : <StateMessage>{run.errorDetail || 'CP-SAT found no non-empty candidate plan. Review the pre-solver exclusions above; no candidate has been fabricated.'}</StateMessage>}</article>
      {selected && <article className="panel"><p className="eyebrow">SELECTED CANDIDATE SOLVER EVIDENCE</p><h3>{selected.name} · {selected.solver?.status}</h3><div className="solver-evidence"><span>Objective<b>{selected.solver?.objective ?? '—'}</b></span><span>Decision variables<b>{selected.solver?.decisionVariables ?? '—'}</b></span><span>Model constraints<b>{selected.solver?.constraints ?? '—'}</b></span><span>Solve time<b>{selected.solver?.timeSeconds == null ? '—' : `${selected.solver.timeSeconds.toFixed(3)} s`}</b></span><span>Tasks scheduled<b>{new Set((selected.blocks || []).flatMap((block) => block.taskIds || [])).size}</b></span><span>Possessions used<b>{selected.blocks?.length || 0}</b></span></div></article>}
      <article className="panel"><p className="eyebrow">SIMULATION HANDOFF</p><h3>Candidate plans are tested under uncertainty next</h3><p className="muted">CP-SAT candidates → Monte Carlo simulation → risk / GATI evaluation → candidate comparison. This planning run already persists simulation-complete candidates; this page does not run a second simulation.</p></article>
      <Link className="workflow-next" to="/workflow/candidate-plans">Continue to Candidate Plans →</Link>
    </>}</section></PageFrame>;
}

export function WorkflowStage({ stageId }) {
  if (stageId === 'optimization') return <OptimizationStage />;
  if (stageId === 'monte-carlo') return <MonteCarloStage />;
  if (stageId === 'risk-analysis') return <RiskAnalysisStage />;
  if (stageId === 'gati-score') return <GatiScoreStage />;
  if (stageId === 'explainability') return <ExplainabilityStage />;
  if (stageId === 'trade-off') return <TradeOffStage />;
  const { loading, error, data } = useWorkflow();
  const stage = stages.find(([id]) => id === stageId) || stages[0];
  const [id, title] = stage;
  const status = stageStatus(id, data);
  const tasks = data?.tasks || [];
  const inputs = data?.planningInputs || {};
  const stageDetails = { 'maintenance-data': ['Maintenance records', tasks.length, 'Canonical work items ready for review'], 'risk-clock': ['Risk inputs', data?.criticalAlerts || 0, 'Authoritative backend RiskClock factor breakdown'], priority: ['Scored tasks', tasks.filter((task) => task.priorityScore != null).length, 'Priority scores feed CP-SAT objective'], 'block-planning': ['Active blocks', data?.activeBlocks || 0, 'Approved, published, or executing plans'], coa: ['COA windows', inputs.coaWindows || 0, 'Persisted Control Office possession windows constrain CP-SAT'], timetable: ['Timetable records', inputs.trains || 0, 'Protected train movements are solver hard constraints'], 'goods-forecast': ['Forecast records', inputs.goodsForecasts || 0, 'Freight demand changes the solver penalty'], bundler: ['Bundle candidates', data?.plans?.length || 0, 'Compatible multi-department work becomes a solver unit'], 'conflict-shield': ['Validated plans', data?.plans?.length || 0, 'Persisted planning candidates'], optimization: ['CP-SAT candidates', data?.plans?.length || 0, 'Generated plans are ranked after simulation'], 'monte-carlo': ['Scenario results', data?.plans?.length || 0, 'Simulation evidence is persisted per candidate'], 'risk-analysis': ['Risk reports', data?.plans?.filter((plan) => plan.metrics?.gati != null).length || 0, 'Risk metrics are attached to evaluated plans'], 'gati-score': ['Scored plans', data?.plans?.filter((plan) => plan.metrics?.gati != null).length || 0, 'GATI ranks plans with persisted delay metrics'], explainability: ['Evidence packs', data?.plans?.length || 0, 'Gemini is explanation-only; scores are deterministic'], 'trade-off': ['Current-run candidates', data?.plans?.length || 0, 'Candidate count only; it is not a baseline-versus-revised comparison'], 'weekly-plan': ['Weekly plans', data?.plans?.filter((plan) => plan.weeklySchedule?.length).length || 0, 'Generated from human-approved final blocks'], 'monthly-plan': ['Monthly plans', data?.plans?.filter((plan) => plan.monthlySchedule?.length).length || 0, 'Generated from final blocks plus remaining demand'] };
  const detail = stageDetails[id] || [title, data?.plans?.length || 0, 'Continue through the controlled planning workflow.'];
  return <PageFrame title={title} eyebrow="WORKFLOW STAGE"><section className="operations-content">{loading ? <LoadingSkeleton /> : error ? <StateMessage error={error} /> : <><article className="panel stage-panel"><span className={`stage-status ${status.toLowerCase()}`}>{status}</span><h3>{detail[0]}</h3><strong className="stage-value">{detail[1]}</strong><p className="muted">{detail[2]}</p>{id === 'maintenance-data' && tasks.length > 0 && <div className="table-wrap"><table><thead><tr><th>Source</th><th>Department</th><th>Asset</th><th>Status</th></tr></thead><tbody>{tasks.map((task) => <tr key={task._id}><td>{task.sourceSystem}</td><td>{task.department}</td><td>{task.assetId}</td><td>{task.status}</td></tr>)}</tbody></table></div>}{detail[1] === 0 && <StateMessage>{detail[2]}</StateMessage>}</article><Link className="workflow-next" to={id === 'monthly-plan' ? '/workflow/approval' : `/workflow/${stages[Math.min(stages.findIndex(([key]) => key === id) + 1, stages.length - 1)][0]}`}>Continue to next stage →</Link></>}</section></PageFrame>;
}
function Metric({ label, value, note }) { return <article className="metric"><p>{label}</p><strong>{value}</strong><small>{note}</small></article>; }

export function CandidatePlansPage({ mode = 'candidate' }) {
  const { loading, error, data } = useWorkflow();
  const plans = data?.plans || []; const title = mode === 'final' ? 'Final recommended plan' : 'Candidate plans';
  const recommend = plans.slice().sort((a, b) => (a.metrics?.gati ?? Infinity) - (b.metrics?.gati ?? Infinity))[0];
  return <PageFrame title={title} eyebrow={mode === 'final' ? 'RECOMMENDATION REVIEW' : 'PLAN COMPARISON'}><section className="operations-content">{loading ? <LoadingSkeleton /> : error ? <StateMessage error={error} /> : !plans.length ? <StateMessage>Generate and persist a planning run to compare candidate plans.</StateMessage> : <><div className="candidate-context"><span className="signal-dot" />{mode === 'final' ? 'The system recommendation is advisory until a control officer approves it.' : 'Compare operational impact before selecting the final plan.'}</div><div className="plan-card-grid">{plans.map((plan, index) => <article className={plan._id === recommend?._id ? 'plan-card recommended' : 'plan-card'} key={plan._id}><div className="panel-heading"><div><p className="eyebrow">{plan._id === recommend?._id ? 'SYSTEM RECOMMENDATION' : `CANDIDATE ${index + 1}`}</p><h3>{plan.name || `Plan ${String.fromCharCode(65 + index)}`}</h3></div><span className={`stage-status ${plan.status?.toLowerCase()}`}>{plan.status}</span></div><div className="plan-measures"><Measure label="GATI" value={plan.metrics?.gati} /><Measure label="Mean delay" value={plan.metrics?.meanDelay} suffix=" min" /><Measure label="CVaR10" value={plan.metrics?.cvar10} /><Measure label="Coverage" value={plan.metrics?.coverage == null ? null : `${Math.round(plan.metrics.coverage * 100)}%`} /><Measure label="Blocks" value={plan.blocks?.length} /><Measure label="Asset downtime" value={plan.metrics?.assetDowntimeMinutes} suffix=" min" /></div>{mode === 'final' && plan._id === recommend?._id && !['APPROVED', 'PUBLISHED'].includes(plan.status) && <Link className="primary" to="/workflow/approval">Send to CTO approval</Link>}</article>)}</div></>}</section></PageFrame>;
}
function Measure({ label, value, suffix = '' }) { return <div><span>{label}</span><strong>{value == null ? '—' : `${value}${suffix}`}</strong></div>; }

export function ApprovalPublish({ publish = false }) {
  const { loading, error, data, refresh } = useWorkflow();
  const approvableStatuses = ['SIMULATION_COMPLETE', 'CANDIDATE', 'SELECTED', 'REVIEW'];
  const plan = data?.plans?.find((item) => publish ? item.status === 'APPROVED' : approvableStatuses.includes(item.status));
  const [toast, setToast] = useState(null);
  const status = publish ? 'PUBLISHED' : 'APPROVED';
  async function update() { if (!plan) return; try { await operationsApi.updatePlanStatus(plan._id, status); await refresh(); setToast({ message: publish ? 'Plan published.' : 'Plan approved.' }); } catch (requestError) { setToast({ message: requestError.response?.data?.detail || 'The plan status could not be updated.', error: true }); } }
  return <PageFrame title={publish ? 'Publish plan' : 'CTO approval'} eyebrow="HUMAN-IN-THE-LOOP GOVERNANCE"><section className="operations-content"><Toast {...toast} />{loading ? <LoadingSkeleton /> : error ? <StateMessage error={error} /> : !plan ? <StateMessage>{publish ? 'An approved plan is required before publication.' : 'A simulation-complete candidate plan is required before CTO approval.'}</StateMessage> : <article className="panel approval-panel"><span className={`stage-status ${plan.status.toLowerCase()}`}>{plan.status}</span><h3>{plan.name || 'Selected plan'}</h3><p className="muted">Approval and publication are explicit status changes on the persisted plan record.</p><button className="primary" onClick={update}>{publish ? 'Publish approved plan' : 'Approve plan'}</button></article>}</section></PageFrame>;
}

function number(value, digits = 1) { return Number.isFinite(value) ? Number(value).toFixed(digits) : '—'; }
function minutes(value) { return Number.isFinite(value) ? `${number(value)} min` : '—'; }
function auditId(value) { const id = value ? String(value) : ''; return id.length > 12 ? `${id.slice(0, 8)}…${id.slice(-4)}` : id || '—'; }

function MonteCarloStage() {
  const { loading, error, data } = useWorkflow();
  const [evidence, setEvidence] = useState({ loading: false, error: '', items: {} });
  const [selectedId, setSelectedId] = useState('');
  const plans = data?.plans || [];
  const run = data?.optimizationRun;

  useEffect(() => {
    let live = true;
    if (!plans.length) { setEvidence({ loading: false, error: '', items: {} }); return () => { live = false; }; }
    setEvidence({ loading: true, error: '', items: {} });
    Promise.all(plans.map(async (plan) => {
      try { const response = await operationsApi.simulations(plan._id); return [String(plan._id), response.data.data]; }
      catch (requestError) { return [String(plan._id), { error: requestError.response?.status === 404 ? 'NOT_RUN' : 'FAILED' }]; }
    })).then((entries) => live && setEvidence({ loading: false, error: '', items: Object.fromEntries(entries) }))
      .catch(() => live && setEvidence({ loading: false, error: 'Simulation evidence could not be loaded.', items: {} }));
    return () => { live = false; };
  }, [data?.optimizationRun?.id]);

  const rows = plans.map((plan) => ({ plan, simulation: evidence.items[String(plan._id)] })).filter(({ simulation }) => simulation && !simulation.error);
  const selected = rows.find(({ plan }) => String(plan._id) === selectedId) || rows[0];
  const runs = rows.map(({ simulation }) => simulation.scenarioCount).filter(Number.isFinite);
  const runsPerCandidate = runs.length && runs.every((value) => value === runs[0]) ? runs[0] : null;
  const totalRuns = runs.reduce((total, value) => total + value, 0);
  const outcomes = selected?.simulation?.outcomes || [];
  const histogram = useMemo(() => {
    if (!outcomes.length) return [];
    const min = Math.min(...outcomes); const max = Math.max(...outcomes); const width = Math.max((max - min) / 10, 1);
    const bins = Array.from({ length: 10 }, (_, index) => ({ label: `${number(min + index * width)}–${number(min + (index + 1) * width)}`, count: 0 }));
    outcomes.forEach((outcome) => { bins[Math.min(9, Math.floor((outcome - min) / width))].count += 1; });
    return bins;
  }, [selected?.plan?._id, outcomes]);
  const tail = outcomes.slice().sort((left, right) => right - left).slice(0, 5);
  const maxBin = Math.max(...histogram.map((bin) => bin.count), 1);

  if (loading || error) return <PageFrame title="Monte Carlo Simulation" eyebrow="OPERATIONAL ROBUSTNESS EVIDENCE"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  if (!run || !plans.length) return <PageFrame title="Monte Carlo Simulation" eyebrow="OPERATIONAL ROBUSTNESS EVIDENCE"><section className="operations-content"><article className="panel"><span className="stage-status pending">NO CANDIDATES AVAILABLE FOR SIMULATION</span><h3>Run CP-SAT Optimization first.</h3><p className="muted">Monte Carlo evidence is displayed only for candidates from the current persisted planning run.</p><Link className="primary" to="/workflow/optimization">Open CP-SAT Optimization</Link></article></section></PageFrame>;
  if (evidence.loading) return <PageFrame title="Monte Carlo Simulation" eyebrow="OPERATIONAL ROBUSTNESS EVIDENCE"><section className="operations-content"><LoadingSkeleton /></section></PageFrame>;
  if (!rows.length) return <PageFrame title="Monte Carlo Simulation" eyebrow="OPERATIONAL ROBUSTNESS EVIDENCE"><section className="operations-content"><article className="panel"><span className="stage-status pending">SIMULATION NOT RUN YET</span><h3>No persisted simulation evidence is available for this planning run.</h3><p className="muted">The authoritative planning workflow normally persists simulation, risk, and GATI evidence together after CP-SAT completes.</p>{evidence.error && <p className="muted">{evidence.error}</p>}<Link className="primary" to="/workflow/optimization">Open CP-SAT Optimization</Link></article></section></PageFrame>;

  return <PageFrame title="Monte Carlo Simulation" eyebrow="OPERATIONAL ROBUSTNESS EVIDENCE"><section className="operations-content">
    <style>{`.mc-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.mc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:16px}.mc-table tr{cursor:pointer}.mc-table tr.selected{background:#eef7fc}.mc-histogram{display:flex;align-items:end;gap:7px;height:175px;padding:14px 4px 0;border-bottom:1px solid #dce8f1}.mc-bin{display:grid;flex:1;min-width:0;height:100%;align-items:end;gap:7px;text-align:center}.mc-bin i{display:block;min-height:3px;border-radius:5px 5px 0 0;background:linear-gradient(180deg,#55b6e8,#1576b4)}.mc-bin span{overflow:hidden;color:#6d8497;font-size:9px;text-overflow:ellipsis;white-space:nowrap}.mc-stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:14px}.mc-stat-grid span,.mc-tail li{padding:10px;border-radius:9px;background:#f7fbfe;color:#6c8395;font-size:11px}.mc-stat-grid b{display:block;margin-top:3px;color:#234e70;font-size:14px}.mc-tail{display:grid;gap:7px;margin:14px 0 0;padding:0;list-style:none}.mc-tail li{display:flex;justify-content:space-between;gap:12px}.mc-flow{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.mc-flow strong{padding:10px 12px;border:1px solid #cce2f1;border-radius:8px;background:#f8fcff;color:#285373;font-size:12px}.mc-flow i{color:#2780b8;font-size:19px;font-style:normal}@media(max-width:800px){.mc-kpis,.mc-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.mc-kpis,.mc-grid,.mc-stat-grid{grid-template-columns:1fr}}`}</style>
    <p className="muted">Stress-test CP-SAT candidate plans under operational uncertainty. Evidence below is persisted by the Python simulation workflow; this page does not generate simulation outcomes.</p>
    <div className="mc-kpis"><Metric label="Candidates simulated" value={rows.length} note="Current CP-SAT run" /><Metric label={runsPerCandidate ? 'Runs / candidate' : 'Run counts'} value={runsPerCandidate || `${Math.min(...runs)}–${Math.max(...runs)}`} note={runsPerCandidate ? 'Persisted scenario count' : 'Varies by candidate'} /><Metric label="Total simulation runs" value={totalRuns} note="Across simulated candidates" /><Metric label="Simulation status" value={rows.length === plans.length ? 'COMPLETED' : 'PARTIAL'} note={`${rows.length} of ${plans.length} candidates`} /></div>
    <section className="workspace"><article className="panel"><p className="eyebrow">UNCERTAINTY MODEL</p><h3>What the current engine evaluates</h3><div className="solver-list"><div><span>Train delay</span><b>Imported scenario input</b></div><div><span>Maintenance overrun</span><b>Imported scenario input</b></div><div><span>Traffic factor</span><b>Scales candidate base delay</b></div><div><span>Asset risk</span><b>Amplifies maintenance overrun</b></div></div><p className="muted">Current workflow scenarios are seeded from MongoDB, which is populated from <code>scenarios.csv</code>. When no records are supplied to the AI endpoint, its fallback is a seeded lognormal delay sample (seed stored per candidate).</p></article><article className="panel"><p className="eyebrow">RISK HANDOFF</p><h3>From feasible plan to decision evidence</h3><div className="mc-flow"><strong>CP-SAT candidate</strong><i>↓</i><strong>Monte Carlo evidence</strong><i>↓</i><strong>Risk analysis</strong><i>↓</i><strong>GATI</strong></div><p className="muted">GATI is persisted from the simulated mean delay and CVaR10: 0.6 × mean delay + 0.4 × CVaR10 delay. Lower is better.</p></article></section>
    <article className="panel"><div className="panel-heading"><div><p className="eyebrow">CANDIDATE ROBUSTNESS</p><h3>Persisted simulation comparison</h3></div><span className="status">Planning run {run.id}</span></div><div className="table-wrap"><table className="mc-table"><thead><tr><th>Candidate</th><th>CP-SAT ID → Simulation ID</th><th>Runs</th><th>Mean delay</th><th>P95 delay</th><th>CVaR10 delay</th><th>Emergency rate</th><th>Status</th></tr></thead><tbody>{rows.map(({ plan, simulation }) => <tr key={plan._id} className={selected?.plan._id === plan._id ? 'selected' : ''} onClick={() => setSelectedId(String(plan._id))}><td><strong>{plan.name}</strong></td><td>{String(plan._id)} → {String(simulation._id)}</td><td>{simulation.scenarioCount}</td><td>{minutes(plan.metrics?.meanDelay)}</td><td>{minutes(plan.metrics?.p95Delay)}</td><td>{minutes(plan.metrics?.cvar10)}</td><td>{plan.metrics?.emergencyRate == null ? '—' : `${number(plan.metrics.emergencyRate * 100)}%`}</td><td><span className="stage-status completed">COMPLETED</span></td></tr>)}</tbody></table></div></article>
    {selected && <section className="mc-grid"><article className="panel"><p className="eyebrow">SELECTED CANDIDATE DISTRIBUTION</p><h3>{selected.plan.name} — delay outcomes</h3><div className="mc-histogram" aria-label="Persisted delay outcome histogram">{histogram.map((bin) => <div className="mc-bin" key={bin.label} title={`${bin.label} min: ${bin.count} runs`}><i style={{ height: `${bin.count / maxBin * 100}%` }} /><span>{bin.label}</span></div>)}</div><p className="muted">Histogram buckets are deterministically grouped from {outcomes.length} persisted delay outcomes. Taller bars show where more runs landed; the right edge is the delay tail.</p><div className="mc-stat-grid"><span>Mean<b>{minutes(selected.plan.metrics?.meanDelay)}</b></span><span>P95<b>{minutes(selected.plan.metrics?.p95Delay)}</b></span><span>CVaR10<b>{minutes(selected.plan.metrics?.cvar10)}</b></span><span>Runs<b>{selected.simulation.scenarioCount}</b></span><span>Seed<b>{selected.simulation.seed}</b></span><span>Worst observed<b>{minutes(outcomes.length ? Math.max(...outcomes) : null)}</b></span></div><p className="muted">CVaR10 is the average delay among the worst 10% of simulated outcomes.</p></article><article className="panel"><p className="eyebrow">TAIL / WORST OUTCOMES</p><h3>Highest-delay persisted runs</h3><ul className="mc-tail">{tail.map((value, index) => <li key={`${value}-${index}`}><span>Rank {index + 1} · outcome {outcomes.indexOf(value) + 1}</span><strong>{minutes(value)}</strong></li>)}</ul><p className="muted">Individual scenario factor records are not retained in the simulation result document, so this view reports real worst outcomes without inventing a cause for each run.</p></article></section>}
    <Link className="workflow-next" to="/workflow/risk-analysis">Continue to Risk Analysis →</Link>
  </section></PageFrame>;
}

function RiskAnalysisStage() {
  const { loading, error, data } = useWorkflow();
  const [evidence, setEvidence] = useState({ loading: false, error: '', items: {} });
  const [selectedId, setSelectedId] = useState('');
  const plans = data?.plans || [];
  const run = data?.optimizationRun;

  useEffect(() => {
    let live = true;
    if (!plans.length) { setEvidence({ loading: false, error: '', items: {} }); return () => { live = false; }; }
    setEvidence({ loading: true, error: '', items: {} });
    Promise.all(plans.map(async (plan) => {
      try {
        const [simulation, risk] = await Promise.all([operationsApi.simulations(plan._id), operationsApi.risk(plan._id)]);
        return [String(plan._id), { simulation: simulation.data.data, risk: risk.data.data }];
      } catch (requestError) { return [String(plan._id), { error: requestError.response?.status === 404 ? 'NOT_RUN' : 'FAILED' }]; }
    })).then((entries) => live && setEvidence({ loading: false, error: '', items: Object.fromEntries(entries) }))
      .catch(() => live && setEvidence({ loading: false, error: 'Risk evidence could not be loaded.', items: {} }));
    return () => { live = false; };
  }, [data?.optimizationRun?.id]);

  const rows = plans.map((plan) => ({ plan, ...evidence.items[String(plan._id)] })).filter((row) => row.simulation && row.risk);
  const selected = rows.find(({ plan }) => String(plan._id) === selectedId) || rows[0];
  const cvars = rows.map(({ risk }) => risk.cvar10).filter(Number.isFinite);
  const emergencyRates = rows.map(({ risk }) => risk.emergencyRate).filter(Number.isFinite);
  const averageCvar = cvars.length ? cvars.reduce((total, value) => total + value, 0) / cvars.length : null;
  const highestEmergency = emergencyRates.length ? Math.max(...emergencyRates) : null;

  if (loading || error) return <PageFrame title="Risk Analysis" eyebrow="SIMULATION DOWNSIDE EVIDENCE"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  if (!run || !plans.length) return <PageFrame title="Risk Analysis" eyebrow="SIMULATION DOWNSIDE EVIDENCE"><section className="operations-content"><article className="panel"><span className="stage-status pending">NO RISK ANALYSIS AVAILABLE</span><h3>Run optimization and simulation first.</h3><p className="muted">Risk reports are persisted for candidates in the current planning run only.</p><Link className="primary" to="/workflow/optimization">Open CP-SAT Optimization</Link></article></section></PageFrame>;
  if (evidence.loading) return <PageFrame title="Risk Analysis" eyebrow="SIMULATION DOWNSIDE EVIDENCE"><section className="operations-content"><LoadingSkeleton /></section></PageFrame>;
  if (!rows.length) return <PageFrame title="Risk Analysis" eyebrow="SIMULATION DOWNSIDE EVIDENCE"><section className="operations-content"><article className="panel"><span className="stage-status pending">RISK ANALYSIS NOT RUN YET</span><h3>No complete risk report is persisted for the current planning run.</h3><p className="muted">The planning workflow persists a risk report after simulation completes.</p>{evidence.error && <p className="muted">{evidence.error}</p>}<Link className="primary" to="/workflow/monte-carlo">Open Monte Carlo Simulation</Link></article></section></PageFrame>;

  return <PageFrame title="Risk Analysis" eyebrow="SIMULATION DOWNSIDE EVIDENCE"><section className="operations-content">
    <style>{`.ra-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.ra-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:16px}.ra-table tr{cursor:pointer}.ra-table tr.selected{background:#eef7fc}.ra-evidence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.ra-evidence span{padding:11px;border-radius:9px;background:#f7fbfe;color:#668095;font-size:11px}.ra-evidence b{display:block;margin-top:4px;color:#254e70;font-size:15px}.ra-flow{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.ra-flow strong{padding:10px 12px;border:1px solid #cce2f1;border-radius:8px;background:#f8fcff;color:#285373;font-size:12px}.ra-flow i{color:#2780b8;font-size:19px;font-style:normal}.ra-copy{display:grid;gap:9px;margin-top:14px}.ra-copy div{padding:11px;border-left:3px solid #71bce6;border-radius:0 8px 8px 0;background:#f8fcff;color:#58738d;font-size:12px}.ra-copy b{color:#245071}@media(max-width:800px){.ra-kpis,.ra-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.ra-kpis,.ra-grid,.ra-evidence{grid-template-columns:1fr}}`}</style>
    <p className="muted">Evaluate downside and robustness of simulated candidate plans. Risk Analysis interprets persisted simulation metrics; it does not re-run Monte Carlo or calculate a frontend risk score.</p>
    <div className="ra-kpis"><Metric label="Candidates assessed" value={rows.length} note="Persisted risk reports" /><Metric label="Average CVaR10" value={minutes(averageCvar)} note="Worst-10% tail average" /><Metric label="Highest emergency rate" value={highestEmergency == null ? '—' : `${number(highestEmergency * 100)}%`} note="Scenario emergency flags" /><Metric label="Risk analysis status" value={rows.length === plans.length ? 'COMPLETED' : 'PARTIAL'} note={`${rows.length} of ${plans.length} candidates`} /></div>
    <article className="panel"><div className="panel-heading"><div><p className="eyebrow">CANDIDATE RISK COMPARISON</p><h3>Current-run persisted risk reports</h3></div><span className="status">Planning run {run.id}</span></div><div className="table-wrap"><table className="ra-table"><thead><tr><th>Candidate</th><th>Candidate → Simulation → Risk report</th><th>Mean delay</th><th>P95 delay</th><th>CVaR10 delay</th><th>Emergency rate</th><th>Assessment</th></tr></thead><tbody>{rows.map(({ plan, simulation, risk }) => <tr key={plan._id} className={selected?.plan._id === plan._id ? 'selected' : ''} onClick={() => setSelectedId(String(plan._id))}><td><strong>{plan.name}</strong></td><td>{String(plan._id)} → {String(simulation._id)} → {String(risk._id)}</td><td>{minutes(risk.meanDelay)}</td><td>{minutes(risk.p95Delay)}</td><td>{minutes(risk.cvar10)}</td><td>{risk.emergencyRate == null ? '—' : `${number(risk.emergencyRate * 100)}%`}</td><td><span className="stage-status completed">COMPLETED</span></td></tr>)}</tbody></table></div></article>
    {selected && <section className="ra-grid"><article className="panel"><p className="eyebrow">SELECTED CANDIDATE RISK EVIDENCE</p><h3>{selected.plan.name}</h3><p className="muted">Candidate {String(selected.plan._id)} · Simulation {String(selected.simulation._id)} · Risk report {String(selected.risk._id)}</p><div className="ra-evidence"><span>Average impact<b>{minutes(selected.risk.meanDelay)}</b></span><span>P95 impact<b>{minutes(selected.risk.p95Delay)}</b></span><span>Tail impact · CVaR10<b>{minutes(selected.risk.cvar10)}</b></span><span>Emergency exposure<b>{selected.risk.emergencyRate == null ? '—' : `${number(selected.risk.emergencyRate * 100)}%`}</b></span><span>Runs assessed<b>{selected.simulation.scenarioCount}</b></span><span>GATI inputs<b>Mean + CVaR10</b></span></div><div className="ra-copy"><div><b>Average vs. tail:</b> average simulated delay is {minutes(selected.risk.meanDelay)}, while the average among the worst 10% is {minutes(selected.risk.cvar10)}.</div><div><b>Emergency evidence:</b> {selected.risk.emergencyRate == null ? 'No scenario emergency evidence was persisted.' : `${number(selected.risk.emergencyRate * 100)}% of selected scenario records were flagged as emergency events.`}</div></div></article><article className="panel"><p className="eyebrow">TAIL / DOWNSIDE EVIDENCE</p><h3>How to read the persisted metrics</h3><div className="solver-list"><div><span>P95 delay</span><b>{minutes(selected.risk.p95Delay)}</b></div><div><span>CVaR10 delay</span><b>{minutes(selected.risk.cvar10)}</b></div><div><span>Cascade probability</span><b>{selected.risk.cascadeProbability == null ? '—' : `${number(selected.risk.cascadeProbability * 100)}%`}</b></div></div><p className="muted">P95 is the 95th percentile of persisted delay outcomes. CVaR10 is the mean of outcomes at or above the 90th-percentile threshold—the current engine’s worst-tail average.</p><p className="muted">The engine does not persist per-factor contribution records, so no causal risk-driver percentages or risk classification are asserted here.</p></article></section>}
    {selected && <section className="workspace"><article className="panel"><p className="eyebrow">GATI INPUTS</p><h3>Verified handoff for {selected.plan.name}</h3><div className="ra-evidence"><span>Mean delay<b>{minutes(selected.risk.meanDelay)}</b></span><span>CVaR10 delay<b>{minutes(selected.risk.cvar10)}</b></span><span>Persisted GATI<b>{number(selected.risk.gati)}</b></span></div><p className="muted">The backend formula is GATI = 0.6 × mean delay + 0.4 × CVaR10 delay. This page exposes the inputs and persists no new score.</p></article><article className="panel"><p className="eyebrow">RISK HANDOFF</p><h3>From simulated outcomes to decision comparison</h3><div className="ra-flow"><strong>Simulation distribution</strong><i>↓</i><strong>Risk metrics<br />Mean · P95 · CVaR · Emergency</strong><i>↓</i><strong>GATI input<br />Mean + tail risk</strong><i>↓</i><strong>GATI score</strong></div></article></section>}
    <Link className="workflow-next" to="/workflow/gati-score">Continue to GATI →</Link>
  </section></PageFrame>;
}

function GatiScoreStage() {
  const { loading, error, data } = useWorkflow();
  const [evidence, setEvidence] = useState({ loading: false, error: '', items: {} });
  const [selectedId, setSelectedId] = useState('');
  const plans = data?.plans || [];
  const run = data?.optimizationRun;

  useEffect(() => {
    let live = true;
    if (!plans.length) { setEvidence({ loading: false, error: '', items: {} }); return () => { live = false; }; }
    setEvidence({ loading: true, error: '', items: {} });
    Promise.all(plans.map(async (plan) => {
      try {
        const [simulation, risk] = await Promise.all([operationsApi.simulations(plan._id), operationsApi.risk(plan._id)]);
        return [String(plan._id), { simulation: simulation.data.data, risk: risk.data.data }];
      } catch (requestError) { return [String(plan._id), { error: requestError.response?.status === 404 ? 'NOT_RUN' : 'FAILED' }]; }
    })).then((entries) => live && setEvidence({ loading: false, error: '', items: Object.fromEntries(entries) }))
      .catch(() => live && setEvidence({ loading: false, error: 'GATI evidence could not be loaded.', items: {} }));
    return () => { live = false; };
  }, [data?.optimizationRun?.id]);

  const rows = plans.map((plan) => ({ plan, ...evidence.items[String(plan._id)] })).filter((row) => row.simulation && row.risk && Number.isFinite(row.risk.gati)).sort((left, right) => left.risk.gati - right.risk.gati);
  const selected = rows.find(({ plan }) => String(plan._id) === selectedId) || rows[0];
  const averageGati = rows.length ? rows.reduce((total, row) => total + row.risk.gati, 0) / rows.length : null;
  const maxGati = Math.max(...rows.map((row) => row.risk.gati), 1);
  const meanContribution = selected ? selected.risk.meanDelay * 0.6 : null;
  const tailContribution = selected ? selected.risk.cvar10 * 0.4 : null;
  const expectedGati = selected ? Number((meanContribution + tailContribution).toFixed(3)) : null;

  if (loading || error) return <PageFrame title="GATI Score" eyebrow="DETERMINISTIC CANDIDATE COMPARISON"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  if (!run || !plans.length) return <PageFrame title="GATI Score" eyebrow="DETERMINISTIC CANDIDATE COMPARISON"><section className="operations-content"><article className="panel"><span className="stage-status pending">NO GATI SCORE AVAILABLE</span><h3>Complete optimization and simulation first.</h3><p className="muted">GATI is persisted only after the current planning workflow has completed simulation and risk analysis.</p><Link className="primary" to="/workflow/optimization">Open CP-SAT Optimization</Link></article></section></PageFrame>;
  if (evidence.loading) return <PageFrame title="GATI Score" eyebrow="DETERMINISTIC CANDIDATE COMPARISON"><section className="operations-content"><LoadingSkeleton /></section></PageFrame>;
  if (!rows.length) return <PageFrame title="GATI Score" eyebrow="DETERMINISTIC CANDIDATE COMPARISON"><section className="operations-content"><article className="panel"><span className="stage-status pending">GATI NOT CALCULATED</span><h3>No persisted GATI evidence is available for the current planning run.</h3><p className="muted">GATI requires the persisted mean-delay and CVaR10 risk metrics from simulation.</p>{evidence.error && <p className="muted">{evidence.error}</p>}<Link className="primary" to="/workflow/risk-analysis">Open Risk Analysis</Link></article></section></PageFrame>;

  return <PageFrame title="GATI Score" eyebrow="DETERMINISTIC CANDIDATE COMPARISON"><section className="operations-content">
    <style>{`.gs-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.gs-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:16px}.gs-table tr{cursor:pointer}.gs-table tr.selected{background:#eef7fc}.gs-formula{display:grid;grid-template-columns:minmax(210px,.8fr) minmax(0,1.2fr);gap:18px;align-items:center}.gs-equation{padding:22px;border-radius:12px;background:linear-gradient(135deg,#eef8ff,#f8fcff);color:#165e94;text-align:center}.gs-equation strong{display:block;font-size:24px}.gs-equation span{display:block;margin-top:7px;color:#638099;font-size:11px;font-weight:700}.gs-terms{display:grid;gap:8px}.gs-terms div{padding:9px 0;border-bottom:1px solid #dce8f1;color:#628097;font-size:12px}.gs-terms b{color:#254f70}.gs-calc{display:grid;gap:9px;margin-top:14px}.gs-calc div{display:flex;justify-content:space-between;gap:15px;padding:10px 12px;border-radius:9px;background:#f7fbfe;color:#668095;font-size:12px}.gs-calc b{color:#254e70}.gs-calc .total{border:1px solid #baddf0;background:#eaf7ff;font-size:14px}.gs-bars{display:grid;gap:11px;margin-top:14px}.gs-bar{display:grid;grid-template-columns:104px minmax(0,1fr) 55px;align-items:center;gap:10px;color:#58748c;font-size:12px}.gs-bar i{height:10px;overflow:hidden;border-radius:999px;background:#e2edf5}.gs-bar b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#55b6e8,#1576b4)}.gs-flow{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.gs-flow strong{padding:10px 12px;border:1px solid #cce2f1;border-radius:8px;background:#f8fcff;color:#285373;font-size:12px}.gs-flow i{color:#2780b8;font-size:19px;font-style:normal}@media(max-width:800px){.gs-kpis,.gs-grid{grid-template-columns:1fr 1fr}.gs-formula{grid-template-columns:1fr}}@media(max-width:520px){.gs-kpis,.gs-grid{grid-template-columns:1fr}.gs-bar{grid-template-columns:88px minmax(0,1fr) 45px}}`}</style>
    <p className="muted">Compare candidate plans using average and tail operational impact. GATI is deterministic backend evidence, not an AI-generated score.</p>
    <div className="gs-kpis"><Metric label="Candidates scored" value={rows.length} note="Current-run persisted scores" /><Metric label="Lowest GATI" value={number(rows[0]?.risk.gati)} note="Weighted delay impact · min" /><Metric label="Average GATI" value={number(averageGati)} note="Across scored candidates · min" /><Metric label="Scoring status" value={rows.length === plans.length ? 'COMPLETED' : 'PARTIAL'} note={`${rows.length} of ${plans.length} candidates`} /></div>
    <article className="panel gs-formula"><div className="gs-equation"><strong>GATI = 0.6 × Mean Delay + 0.4 × CVaR10 Delay</strong><span>Lower GATI = lower combined simulated delay impact</span></div><div className="gs-terms"><div><b>Mean delay · 0.6 weight</b> — average operational impact across simulations.</div><div><b>CVaR10 delay · 0.4 weight</b> — average delay among outcomes at or above the 90th-percentile threshold.</div><div><b>Units</b> — both inputs and the resulting weighted measure are minutes; there is no normalization or score band.</div></div></article>
    <article className="panel"><div className="panel-heading"><div><p className="eyebrow">CANDIDATE SCORE COMPARISON</p><h3>Persisted backend calculations</h3></div><span className="status">Planning run {run.id}</span></div><div className="table-wrap"><table className="gs-table"><thead><tr><th>Candidate</th><th>Mean delay</th><th>CVaR10</th><th>Mean contribution</th><th>Tail contribution</th><th>GATI</th><th>Status</th></tr></thead><tbody>{rows.map(({ plan, risk }) => <tr key={plan._id} className={selected?.plan._id === plan._id ? 'selected' : ''} onClick={() => setSelectedId(String(plan._id))}><td><strong>{plan.name}</strong></td><td>{minutes(risk.meanDelay)}</td><td>{minutes(risk.cvar10)}</td><td>{number(risk.meanDelay * 0.6)} min</td><td>{number(risk.cvar10 * 0.4)} min</td><td><strong>{number(risk.gati)} min</strong></td><td><span className="stage-status completed">COMPLETED</span></td></tr>)}</tbody></table></div></article>
    {selected && <section className="gs-grid"><article className="panel"><p className="eyebrow">SELECTED CANDIDATE CALCULATION</p><h3>{selected.plan.name}</h3><p className="muted">Candidate {String(selected.plan._id)} · Simulation {String(selected.simulation._id)} · Risk report {String(selected.risk._id)} · {selected.simulation.scenarioCount} runs</p><div className="gs-calc"><div><span>Mean contribution</span><b>0.6 × {number(selected.risk.meanDelay, 5)} = {number(meanContribution, 5)} min</b></div><div><span>Tail contribution</span><b>0.4 × {number(selected.risk.cvar10, 5)} = {number(tailContribution, 5)} min</b></div><div className="total"><span>Persisted GATI</span><b>{number(selected.risk.gati, 3)} min</b></div></div><p className="muted">Display contributions use full-precision persisted inputs for transparency. The final score remains the authoritative Python-calculated and persisted value: expected {number(expectedGati, 3)} / persisted {number(selected.risk.gati, 3)}.</p></article><article className="panel"><p className="eyebrow">SCORE INTERPRETATION</p><h3>Relative combined delay impact</h3><div className="gs-bars">{rows.map(({ plan, risk }) => <div className="gs-bar" key={plan._id}><span>{plan.name}</span><i><b style={{ width: `${risk.gati / maxGati * 100}%` }} /></i><strong>{number(risk.gati)} min</strong></div>)}</div><p className="muted">Bars compare persisted weighted minutes, not percentages. Lower values indicate lower weighted average-plus-tail delay impact only; they do not claim a universally best plan.</p></article></section>}
    <section className="workspace"><article className="panel"><p className="eyebrow">TRADE-OFF DIAL RELATIONSHIP</p><h3>Separate from GATI weights</h3><p className="muted">The Trade-off Dial supplies CP-SAT objective preferences such as priority, freight, and downtime. It does not modify GATI’s fixed 0.6 / 0.4 calculation.</p></article><article className="panel"><p className="eyebrow">EXPLAINABILITY HANDOFF</p><h3>Evidence passed forward</h3><div className="gs-flow"><strong>Simulation<br />Mean + tail distribution</strong><i>↓</i><strong>Risk analysis<br />Interpretable downside</strong><i>↓</i><strong>GATI<br />Deterministic comparison</strong><i>↓</i><strong>Show your work</strong></div><p className="muted">Explainability may describe persisted candidate evidence; it does not calculate or alter GATI.</p></article></section>
    <Link className="workflow-next" to="/workflow/explainability">Continue to Explainability →</Link>
  </section></PageFrame>;
}

function ExplainabilityStage() {
  const { loading, error, data } = useWorkflow();
  const [evidence, setEvidence] = useState({ loading: false, error: '', items: {}, shared: {} });
  const [selectedId, setSelectedId] = useState('');
  const [question, setQuestion] = useState('Explain this candidate using the supplied deterministic evidence.');
  const [ai, setAi] = useState({ loading: false, error: '', answer: '', provider: '' });
  const plans = data?.plans || [];
  const run = data?.optimizationRun;

  useEffect(() => {
    let live = true;
    if (!plans.length) { setEvidence({ loading: false, error: '', items: {}, shared: {} }); return () => { live = false; }; }
    setEvidence({ loading: true, error: '', items: {}, shared: {} });
    Promise.all([Promise.all(plans.map(async (plan) => {
      try { const [simulation, risk] = await Promise.all([operationsApi.simulations(plan._id), operationsApi.risk(plan._id)]); return [String(plan._id), { simulation: simulation.data.data, risk: risk.data.data }]; }
      catch (requestError) { return [String(plan._id), { error: requestError.response?.status === 404 ? 'NOT_RUN' : 'FAILED' }]; }
    })), Promise.allSettled([operationsApi.coa(), operationsApi.timetable(), operationsApi.goodsForecast()])]).then(([entries, sharedResults]) => {
      if (!live) return;
      const [coa, timetable, goods] = sharedResults.map((result) => result.status === 'fulfilled' ? result.value.data.data : null);
      setEvidence({ loading: false, error: '', items: Object.fromEntries(entries), shared: { coa, timetable, goods } });
    }).catch(() => live && setEvidence({ loading: false, error: 'Deterministic evidence could not be loaded.', items: {}, shared: {} }));
    return () => { live = false; };
  }, [data?.optimizationRun?.id]);

  const rows = plans.map((plan) => ({ plan, ...evidence.items[String(plan._id)] })).filter((row) => row.simulation && row.risk);
  const selected = rows.find(({ plan }) => String(plan._id) === selectedId) || rows[0];
  const taskById = Object.fromEntries((data?.tasks || []).map((task) => [String(task._id), task]));
  const selectedTasks = selected ? [...new Set(selected.plan.blocks.flatMap((block) => block.taskIds || []))].map((id) => taskById[String(id)]).filter(Boolean) : [];
  const coaWindows = evidence.shared.coa?.windows || [];
  const timetableChecks = evidence.shared.timetable?.coaChecks || [];
  const goodsForecasts = evidence.shared.goods?.forecasts || [];
  const blocks = selected?.plan.blocks || [];
  const operationalRows = blocks.map((block) => ({ block, coa: coaWindows.find((window) => window.id === block.windowId), timetable: timetableChecks.find((check) => check.id === block.windowId), goods: goodsForecasts.filter((forecast) => forecast.sectionId === block.sectionId && Math.max(forecast.startMin, block.startMin) < Math.min(forecast.endMin, block.endMin)) }));
  const meanContribution = selected ? selected.risk.meanDelay * 0.6 : null;
  const tailContribution = selected ? selected.risk.cvar10 * 0.4 : null;
  const evidencePayload = selected ? { candidate: { id: String(selected.plan._id), name: selected.plan.name, blocks: selected.plan.blocks, solver: selected.plan.solver }, maintenanceEvidence: selectedTasks.map((task) => ({ id: String(task._id), source: task.sourceSystem, department: task.department, section: task.sectionId, priority: task.priorityScore, factors: task.priorityFactors })), operationalEvidence: operationalRows.map(({ block, coa, timetable, goods }) => ({ block, coa, timetable: timetable ? { result: timetable.result, safetyMarginMin: timetable.safetyMarginMin } : null, goodsPressure: goods.map((forecast) => forecast.trafficIntensity) })), simulationEvidence: { id: String(selected.simulation._id), runs: selected.simulation.scenarioCount, meanDelay: selected.risk.meanDelay, p95Delay: selected.risk.p95Delay, cvar10: selected.risk.cvar10, emergencyRate: selected.risk.emergencyRate }, riskEvidence: { id: String(selected.risk._id), cascadeProbability: selected.risk.cascadeProbability }, gatiEvidence: { formula: '0.6 * mean_delay + 0.4 * cvar10_delay', gati: selected.risk.gati } } : null;
  async function askAi(event) { event.preventDefault(); if (!evidencePayload || ai.loading) return; setAi({ loading: true, error: '', answer: '', provider: '' }); try { const response = await operationsApi.explanation({ question, evidence: evidencePayload }); const result = response.data.data; setAi({ loading: false, error: '', answer: result.text || result.answer || '', provider: result.provider || 'unknown' }); } catch (requestError) { setAi({ loading: false, error: requestError.response?.data?.detail || 'AI explanation is unavailable. Deterministic evidence remains available.', answer: '', provider: '' }); } }

  if (loading || error) return <PageFrame title="Show Your Work" eyebrow="AUDITABLE DECISION TRACE"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  if (!run || !plans.length) return <PageFrame title="Show Your Work" eyebrow="AUDITABLE DECISION TRACE"><section className="operations-content"><article className="panel"><span className="stage-status pending">NO EXPLAINABILITY EVIDENCE AVAILABLE</span><h3>Complete optimization and evaluation first.</h3><p className="muted">Show Your Work traces evidence for candidates in the current planning run only.</p><Link className="primary" to="/workflow/optimization">Open CP-SAT Optimization</Link></article></section></PageFrame>;
  if (evidence.loading) return <PageFrame title="Show Your Work" eyebrow="AUDITABLE DECISION TRACE"><section className="operations-content"><LoadingSkeleton /></section></PageFrame>;
  if (!rows.length) return <PageFrame title="Show Your Work" eyebrow="AUDITABLE DECISION TRACE"><section className="operations-content"><article className="panel"><span className="stage-status pending">EVALUATION EVIDENCE NOT AVAILABLE</span><h3>No complete simulation and risk evidence is persisted for this run.</h3><Link className="primary" to="/workflow/monte-carlo">Open Monte Carlo Simulation</Link></article></section></PageFrame>;

  return <PageFrame title="Show Your Work" eyebrow="AUDITABLE DECISION TRACE"><section className="operations-content">
    <style>{`.ex-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.ex-selector{display:flex;flex-wrap:wrap;gap:9px;margin-top:14px}.ex-selector button{padding:10px 13px;border:1px solid #c9dfed;border-radius:8px;background:#f8fcff;color:#315a79;font-weight:800}.ex-selector button.selected{border-color:#1686d1;background:#e4f4ff;color:#12649e}.ex-trace{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:14px}.ex-trace div{min-width:105px;flex:1;padding:11px;border:1px solid #d4e5f0;border-radius:9px;background:#f9fcff;color:#5c7891;font-size:10px;font-weight:700;text-align:center}.ex-trace b{display:block;margin-bottom:4px;color:#254f70;font-size:11px}.ex-trace i{color:#2780b8;font-size:18px;font-style:normal}.ex-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:16px}.ex-facts{display:grid;gap:8px;margin-top:12px}.ex-facts div{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-top:1px solid #dce8f1;color:#668095;font-size:12px}.ex-facts b{color:#254f70;text-align:right}.ex-task-table td{vertical-align:top}.ex-pills{display:flex;flex-wrap:wrap;gap:5px}.ex-pills span{padding:3px 6px;border-radius:999px;background:#eaf5fc;color:#28678e;font-size:9px;font-weight:700}.ex-ai{display:grid;gap:12px}.ex-ai form{display:grid;gap:9px}.ex-ai textarea{min-height:72px;padding:10px;border:1px solid #c8deed;border-radius:8px;color:#315a79;font:inherit;resize:vertical}.ex-audit{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:12px}.ex-audit span{overflow-wrap:anywhere;padding:10px;border-radius:8px;background:#f7fbfe;color:#668095;font-size:10px}.ex-audit b{display:block;margin-bottom:4px;color:#254f70;font-size:11px}@media(max-width:800px){.ex-kpis,.ex-grid{grid-template-columns:1fr 1fr}.ex-audit{grid-template-columns:1fr 1fr}}@media(max-width:520px){.ex-kpis,.ex-grid,.ex-audit{grid-template-columns:1fr}.ex-trace{align-items:stretch}.ex-trace i{display:none}}`}</style>
    <p className="muted">Trace every candidate back to deterministic planning evidence. Gemini is an optional explanation-only layer and never calculates, changes, or ranks the evidence below.</p>
    <div className="ex-kpis"><Metric label="Candidates explained" value={rows.length} note="Current evaluated candidates" /><Metric label="Evidence sources" value={evidence.shared.coa && evidence.shared.timetable && evidence.shared.goods ? 8 : 6} note="Available deterministic systems" /><Metric label="Deterministic checks" value={selectedTasks.length + blocks.length} note="Scheduled tasks + possessions" /><Metric label="Explanation status" value="ON DEMAND" note="Gemini is optional" /></div>
    <article className="panel"><p className="eyebrow">SELECT CANDIDATE</p><h3>Current planning-run evidence</h3><div className="ex-selector">{rows.map(({ plan, risk }) => <button key={plan._id} className={selected?.plan._id === plan._id ? 'selected' : ''} onClick={() => { setSelectedId(String(plan._id)); setAi({ loading: false, error: '', answer: '', provider: '' }); }}>{plan.name} · {plan.blocks.length} work item{plan.blocks.length === 1 ? '' : 's'} · {minutes(risk.meanDelay)} · GATI {number(risk.gati)}</button>)}</div><div className="ex-trace"><div><b>MAINTENANCE</b>{selectedTasks.length} scheduled task{selectedTasks.length === 1 ? '' : 's'}</div><i>↓</i><div><b>PRIORITY</b>Persisted task factors</div><i>↓</i><div><b>FEASIBILITY</b>{blocks.length} COA possession{blocks.length === 1 ? '' : 's'}</div><i>↓</i><div><b>CP-SAT</b>{selected?.plan.solver?.status || '—'}</div><i>↓</i><div><b>MONTE CARLO</b>{selected?.simulation.scenarioCount || '—'} runs</div><i>↓</i><div><b>RISK / GATI</b>{number(selected?.risk.gati)} min</div></div></article>
    <section className="ex-grid"><article className="panel"><p className="eyebrow">WHY THIS PLAN? · DETERMINISTIC EVIDENCE</p><h3>Candidate-specific facts</h3><div className="ex-facts"><div><span>Why work was considered</span><b>{selectedTasks.length} persisted maintenance task{selectedTasks.length === 1 ? '' : 's'}</b></div><div><span>Operational window evidence</span><b>{operationalRows.every(({ coa }) => coa?.status === 'AVAILABLE') ? 'Available COA window(s)' : 'See possession evidence'}</b></div><div><span>What CP-SAT optimized</span><b>{selected?.plan.solver?.objectiveDescription || 'Persisted solver objective'}</b></div><div><span>Simulation performance</span><b>Mean {minutes(selected?.risk.meanDelay)} · CVaR10 {minutes(selected?.risk.cvar10)}</b></div><div><span>GATI result</span><b>{number(selected?.risk.gati)} weighted min</b></div></div></article><article className="panel"><p className="eyebrow">SOLVER + RISK EVIDENCE</p><h3>Persisted calculation chain</h3><div className="ex-facts"><div><span>Solver / objective</span><b>{selected?.plan.solver?.status} · {number(selected?.plan.solver?.objective)}</b></div><div><span>Profile weights</span><b>{Object.entries(selected?.plan.solver?.weights || {}).map(([key, value]) => `${key} ${value}`).join(' · ') || '—'}</b></div><div><span>Simulation</span><b>{selected?.simulation.scenarioCount} runs · P95 {minutes(selected?.risk.p95Delay)}</b></div><div><span>Risk report</span><b>CVaR10 {minutes(selected?.risk.cvar10)} · Emergency {number((selected?.risk.emergencyRate || 0) * 100)}%</b></div><div><span>GATI calculation</span><b>0.6 × mean + 0.4 × CVaR10 = {number(selected?.risk.gati)} min</b></div></div></article></section>
    <article className="panel"><p className="eyebrow">MAINTENANCE / PRIORITY EVIDENCE</p><h3>Work actually included in {selected?.plan.name}</h3><div className="table-wrap"><table className="ex-task-table"><thead><tr><th>Task</th><th>Source</th><th>Department / section</th><th>Priority</th><th>Deterministic factors</th><th>Scheduled possession</th></tr></thead><tbody>{selectedTasks.map((task) => { const matching = blocks.filter((block) => (block.taskIds || []).includes(String(task._id))); return <tr key={task._id}><td><strong>{task.sourceId}</strong><br /><small>{task.defectType}</small></td><td>{task.sourceSystem}</td><td>{task.department}<br /><small>{task.sectionId}</small></td><td>{number(task.priorityScore, 3)}</td><td><div className="ex-pills">{(task.priorityFactors?.influencing_factors || []).map((factor) => <span key={factor}>{factor}</span>)}</div></td><td>{matching.map((block) => `${block.windowId} · ${block.startMin}–${block.endMin}`).join(', ')}</td></tr>; })}</tbody></table></div></article>
    <section className="ex-grid"><article className="panel"><p className="eyebrow">OPERATIONAL FEASIBILITY EVIDENCE</p><h3>Persisted assignments and source checks</h3>{operationalRows.map(({ block, coa, timetable, goods }) => <div className="ex-facts" key={`${block.windowId}-${block.sectionId}`}><div><span>{block.windowId} · {block.sectionId}</span><b>{block.startMin}–{block.endMin} min</b></div><div><span>COA status</span><b>{coa?.status || 'Not available in COA read model'}</b></div><div><span>Timetable check</span><b>{timetable ? `${timetable.result} · ${timetable.safetyMarginMin} min margin` : 'Not available in timetable read model'}</b></div><div><span>Goods forecast overlap</span><b>{goods.length ? goods.map((item) => item.trafficIntensity).join(', ') : 'None recorded'}</b></div></div>)}<p className="muted">These are source-system checks; this page does not re-run conflict logic.</p></article><article className="panel ex-ai"><p className="eyebrow">AI EXPLANATION · GEMINI</p><h3>Explanation-only layer</h3><p className="muted">Generated only from the structured deterministic evidence shown on this page. Gemini cannot calculate scores, simulate outcomes, optimize plans, or recommend unsupported changes.</p><form onSubmit={askAi}><textarea value={question} onChange={(event) => setQuestion(event.target.value)} aria-label="Explanation question" /><button className="primary" disabled={ai.loading}>{ai.loading ? 'Generating explanation…' : 'Explain supplied evidence'}</button></form>{ai.error && <div className="workflow-message error-state"><strong>AI EXPLANATION UNAVAILABLE</strong><p>{ai.error}</p></div>}{ai.provider === 'local-evidence-summary' && <div className="workflow-message"><strong>DETERMINISTIC EVIDENCE AVAILABLE</strong><p>Gemini is not configured. The complete deterministic trace remains available above.</p></div>}{ai.answer && ai.provider !== 'local-evidence-summary' && <div className="answer"><strong>AI-generated explanation</strong><p>{ai.answer}</p></div>}</article></section>
    <article className="panel"><p className="eyebrow">AUDIT REFERENCES</p><h3>Current-run deterministic identifiers</h3><div className="ex-audit"><span><b>Planning run</b>{run.id}</span><span><b>Candidate</b>{String(selected?.plan._id)}</span><span><b>Simulation result</b>{String(selected?.simulation._id)}</span><span><b>Risk report</b>{String(selected?.risk._id)}</span><span><b>Evidence pack</b>Not a persisted domain object</span><span><b>Source systems</b>Maintenance · COA · timetable · CP-SAT · simulation · risk · GATI</span></div></article>
    <article className="panel"><p className="eyebrow">TRADE-OFF DIAL HANDOFF</p><h3>Understand evidence before adjusting preferences</h3><div className="ex-trace"><div><b>UNDERSTAND</b>Current plan evidence</div><i>↓</i><div><b>SHOW YOUR WORK</b>Read-only audit trace</div><i>↓</i><div><b>ADJUST</b>Trade-off preferences</div><i>↓</i><div><b>RE-RUN</b>CP-SAT workflow</div></div></article>
    <Link className="workflow-next" to="/workflow/trade-off">Continue to Trade-off Dial →</Link>
  </section></PageFrame>;
}

function TradeOffStage() {
  const { loading, error, data, refresh } = useWorkflow();
  const [weights, setWeights] = useState(null);
  const [baseline, setBaseline] = useState(null);
  const [revised, setRevised] = useState(null);
  const [execution, setExecution] = useState({ phase: 'READY', error: '' });
  const plans = data?.plans || [];
  const run = data?.optimizationRun;
  const reference = plans[0];
  const currentWeights = reference?.solver?.weights || {};
  const defaultWeights = run?.evidence?.profiles?.find((profile) => profile.profile === 1)?.weights || currentWeights;
  const activeWeights = weights || currentWeights;
  const changed = Object.keys(currentWeights).filter((key) => activeWeights[key] !== currentWeights[key]);
  const pendingChanges = changed.length ? 'CHANGED' : 'NONE';
  const latestReRun = execution.phase !== 'READY' ? execution.phase : run?.parentRunId ? run.status : 'NO RE-RUN YET';

  async function rerun() {
    if (execution.phase === 'RE-OPTIMIZING' || !run || !reference) return;
    setBaseline({ run: { id: run.id }, plan: reference, weights: currentWeights }); setExecution({ phase: 'RE-OPTIMIZING', error: '' }); setRevised(null);
    try {
      const response = await planningApi.generate({ corridorId: data.corridorId, tradeoffWeights: activeWeights, baselineRunId: run.id });
      const result = response.data.data; setExecution({ phase: 'EVALUATING', error: '' }); setRevised({ run: result.run, plan: result.plans?.[0] || null, weights: activeWeights }); await refresh(); setExecution({ phase: 'COMPLETED', error: '' });
    } catch (requestError) { setExecution({ phase: 'FAILED', error: requestError.response?.data?.detail || 'Re-optimization could not be completed.' }); }
  }
  const compare = (label, left, right) => <div className="td-compare-row"><span>{label}</span><b>{left ?? '—'}</b><b>{right ?? '—'}</b></div>;
  const difference = revised?.plan && baseline?.plan ? { added: revised.plan.blocks.flatMap((block) => block.taskIds || []).filter((id) => !baseline.plan.blocks.some((block) => (block.taskIds || []).includes(id))), removed: baseline.plan.blocks.flatMap((block) => block.taskIds || []).filter((id) => !revised.plan.blocks.some((block) => (block.taskIds || []).includes(id))), windowsChanged: JSON.stringify(baseline.plan.blocks.map((block) => block.windowId).sort()) !== JSON.stringify(revised.plan.blocks.map((block) => block.windowId).sort()), bundlesChanged: JSON.stringify(baseline.plan.blocks.map((block) => block.bundleId).filter(Boolean).sort()) !== JSON.stringify(revised.plan.blocks.map((block) => block.bundleId).filter(Boolean).sort()) } : null;

  if (loading || error) return <PageFrame title="Trade-Off Dial" eyebrow="HUMAN-IN-THE-LOOP RE-OPTIMIZATION"><section className="operations-content">{loading ? <LoadingSkeleton /> : <StateMessage error={error} />}</section></PageFrame>;
  if (!run || !reference) return <PageFrame title="Trade-Off Dial" eyebrow="HUMAN-IN-THE-LOOP RE-OPTIMIZATION"><section className="operations-content"><article className="panel"><span className="stage-status pending">NO BASELINE AVAILABLE</span><h3>Complete optimization and evaluation first.</h3><Link className="primary" to="/workflow/optimization">Open CP-SAT Optimization</Link></article></section></PageFrame>;
  return <PageFrame title="Trade-Off Dial" eyebrow="HUMAN-IN-THE-LOOP RE-OPTIMIZATION"><section className="operations-content">
    <style>{`.td-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.td-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:16px}.td-controls{display:grid;gap:14px;margin-top:14px}.td-control{display:grid;grid-template-columns:150px minmax(0,1fr) 42px;align-items:center;gap:12px}.td-control label{color:#315a78;font-size:12px;font-weight:800}.td-control input{width:100%;accent-color:#1686d1}.td-control b{color:#1e5d8d;text-align:right}.td-note{padding:11px;border-left:3px solid #64b6e7;border-radius:0 8px 8px 0;background:#f8fcff;color:#5b7891;font-size:12px}.td-weights,.td-compare{display:grid;gap:8px;margin-top:13px}.td-weights div,.td-compare-row{display:grid;grid-template-columns:1fr 80px 80px;gap:10px;padding:9px;border-radius:8px;background:#f7fbfe;color:#668095;font-size:11px}.td-compare-row b,.td-weights b{color:#254f70;text-align:right}.td-compare-row:first-child{background:#eaf7ff;font-weight:800}.td-flow{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.td-flow strong{padding:10px 12px;border:1px solid #cce2f1;border-radius:8px;background:#f8fcff;color:#285373;font-size:12px}.td-flow i{color:#2780b8;font-size:19px;font-style:normal}.td-pending{padding:7px 10px;border:1px solid #cce2f1;border-radius:8px;background:#f8fcff;color:#315a78;font-size:11px;font-weight:800}@media(max-width:800px){.td-kpis,.td-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.td-kpis,.td-grid{grid-template-columns:1fr}.td-control{grid-template-columns:1fr}.td-weights div,.td-compare-row{grid-template-columns:1fr 1fr}}`}</style>
    <p className="muted">Adjust real CP-SAT soft-objective preferences, then re-run the same authoritative workflow: CP-SAT → simulation → risk → GATI. Hard operational constraints remain enforced.</p>
    <div className="td-kpis"><Metric label="Original / Baseline Run" value={run.parentRunId ? 'Original evaluated plan' : 'Current evaluated plan'} note={run.parentRunId ? `Audit ID: ${auditId(run.parentRunId)}` : 'No parent run'} /><Metric label="Current Re-optimization" value={run.parentRunId ? 'Re-optimized plan' : 'Current evaluated plan'} note={run.parentRunId ? `Re-optimized from original · Audit ID: ${auditId(run.id)}` : `Audit ID: ${auditId(run.id)}`} /><Metric label="Reference candidate" value={reference.name || 'Candidate'} note={`Profile ${reference.solver?.profile || '—'}`} /><Metric label="Latest Re-run" value={latestReRun} note={execution.phase === 'RE-OPTIMIZING' ? 'CP-SAT is running; evaluation follows in this request' : execution.phase === 'EVALUATING' ? 'Simulation, risk, and GATI are being persisted' : run.parentRunId ? 'Persisted re-optimization status' : 'No persisted re-optimization'} /></div>
    <section className="td-grid"><article className="panel"><p className="eyebrow">CURRENT PLAN / BASELINE</p><h3>{reference.name || 'Candidate'}</h3><div className="solver-list"><div><span>Candidate</span><b>{reference.name || 'Candidate'}</b></div><div><span>Audit ID</span><b>{auditId(reference._id)}</b></div><div><span>Scheduled work / possessions</span><b>{reference.blocks?.reduce((sum, block) => sum + (block.taskIds?.length || 0), 0)} / {reference.blocks?.length}</b></div><div><span>Scheduled task IDs</span><b>{reference.blocks?.flatMap((block) => block.taskIds || []).join(', ') || '—'}</b></div><div><span>Mean / CVaR10</span><b>{minutes(reference.metrics?.meanDelay)} / {minutes(reference.metrics?.cvar10)}</b></div><div><span>GATI</span><b>{number(reference.metrics?.gati)} min</b></div></div></article><article className="panel"><p className="eyebrow">HARD CONSTRAINTS REMAIN ENFORCED</p><h3>Not adjustable by this dial</h3><div className="solver-list"><div><span>COA blocked windows</span><b>Excluded</b></div><div><span>Window fit / department eligibility</span><b>Required</b></div><div><span>Train protection</span><b>Required safety margin</b></div><div><span>Section / resource capacity</span><b>Hard constraint</b></div></div></article></section>
    <article className="panel"><p className="eyebrow">OPTIMIZATION PREFERENCES</p><h3>Real CP-SAT objective coefficients</h3><p className="td-note">Weights are independent integers; the optimizer does not normalize them. Priority and downtime increase their respective objective terms; freight increases the penalty for overlapping freight demand.</p><div className="td-controls">{[['priority', 'Maintenance priority', 'Higher weight favors task priority.'], ['freight', 'Freight penalty', 'Higher weight penalizes overlapping freight demand.'], ['downtime', 'Availability impact', 'Higher weight favors maintenance with greater availability impact.']].map(([key, label, note]) => <div key={key}><div className="td-control"><label htmlFor={`weight-${key}`}>{label}</label><input id={`weight-${key}`} type="range" min="0" max="150" step="1" value={activeWeights[key] ?? 0} onChange={(event) => setWeights({ ...activeWeights, [key]: Number(event.target.value) })} disabled={execution.phase === 'RE-OPTIMIZING'} /><b>{activeWeights[key] ?? 0}</b></div><small className="muted">{note}</small></div>)}</div><div className="td-weights"><div><span>Objective term</span><b>Current</b><b>Adjusted</b></div>{Object.keys(activeWeights).map((key) => <div key={key}><span>{key}</span><b>{currentWeights[key]}</b><b>{activeWeights[key]}</b></div>)}</div><div className="toolbar"><span className="td-pending">Pending changes: {pendingChanges}</span><button className="secondary" onClick={() => setWeights(currentWeights)} disabled={execution.phase === 'RE-OPTIMIZING'}>Reset to Current</button><button className="secondary" onClick={() => setWeights(defaultWeights)} disabled={execution.phase === 'RE-OPTIMIZING'}>Reset to Default Profile</button><button className="primary" onClick={rerun} disabled={execution.phase === 'RE-OPTIMIZING'}>{execution.phase === 'RE-OPTIMIZING' ? 'Re-optimizing and evaluating…' : 'Re-run CP-SAT'}</button></div>{changed.length > 0 ? <p className="muted">Custom configuration: {changed.map((key) => `${key} ${currentWeights[key]} → ${activeWeights[key]}`).join(' · ')}. No future GATI or delay is predicted before evaluation.</p> : <p className="muted">No objective weights changed. Re-running will use the current coefficients; no future GATI or delay is predicted before evaluation.</p>}{execution.error && <div className="workflow-message error-state"><strong>RE-OPTIMIZATION FAILED</strong><p>{execution.error}</p></div>}</article>
    {revised && <section className="td-grid"><article className="panel"><p className="eyebrow">ORIGINAL VS REVISED</p><h3>Actual persisted evaluation evidence</h3><div className="td-compare">{compare('Metric', 'Original', 'Revised')}{compare('Run', 'Original evaluated plan', 'Re-optimized plan')}{compare('Candidate', baseline.plan.name || 'Candidate', revised.plan?.name || 'Candidate')}{compare('Scheduled work', baseline.plan.blocks.reduce((sum, block) => sum + (block.taskIds?.length || 0), 0), revised.plan?.blocks.reduce((sum, block) => sum + (block.taskIds?.length || 0), 0))}{compare('Mean delay', minutes(baseline.plan.metrics?.meanDelay), minutes(revised.plan?.metrics?.meanDelay))}{compare('P95 delay', minutes(baseline.plan.metrics?.p95Delay), minutes(revised.plan?.metrics?.p95Delay))}{compare('CVaR10', minutes(baseline.plan.metrics?.cvar10), minutes(revised.plan?.metrics?.cvar10))}{compare('Emergency rate', `${number((baseline.plan.metrics?.emergencyRate || 0) * 100)}%`, `${number((revised.plan?.metrics?.emergencyRate || 0) * 100)}%`)}{compare('GATI', number(baseline.plan.metrics?.gati), number(revised.plan?.metrics?.gati))}</div><p className="muted">Audit IDs: original run {auditId(baseline.run.id)} · revised run {auditId(revised.run._id || revised.run.id)} · original candidate {auditId(baseline.plan._id)} · revised candidate {auditId(revised.plan?._id)}</p></article><article className="panel"><p className="eyebrow">PLAN DIFFERENCES</p><h3>{difference?.added.length || difference?.removed.length || difference?.windowsChanged || difference?.bundlesChanged ? 'Schedule changed under revised preferences' : 'Same plan remains optimal under these preferences'}</h3><div className="solver-list"><div><span>Tasks added</span><b>{difference?.added.length || 0}</b></div><div><span>Tasks removed</span><b>{difference?.removed.length || 0}</b></div><div><span>Possession windows changed</span><b>{difference?.windowsChanged ? 'YES' : 'NO'}</b></div><div><span>Bundles changed</span><b>{difference?.bundlesChanged ? 'YES' : 'NO'}</b></div><div><span>Revised run linkage</span><b>Re-optimized from original</b></div></div><p className="muted">The original run remains persisted. The revised run records its baseline run ID and submitted trade-off weights for auditability.</p></article></section>}
    <article className="panel"><p className="eyebrow">HUMAN-IN-THE-LOOP</p><h3>Preferences change the planning objective, not the evaluation formula</h3><div className="td-flow"><strong>System<br />Evaluated baseline</strong><i>↓</i><strong>Human<br />Adjusts soft preferences</strong><i>↓</i><strong>System<br />Re-optimizes with hard constraints</strong><i>↓</i><strong>Human<br />Reviews factual comparison</strong></div><p className="muted">GATI remains fixed at 0.6 × mean delay + 0.4 × CVaR10 delay, so original and revised candidates use the same evaluation framework. This page does not approve or finalize a plan.</p></article>
    <Link className="workflow-next" to="/workflow/final-plan">Continue to Final Plan →</Link>
  </section></PageFrame>;
}
